def browser_ops(homepage, ops):
    hist, i, out = [homepage], 0, []
    for op in ops:
        if op[0] == 'visit':
            hist = hist[:i + 1] + [op[1]]
            i += 1
        elif op[0] == 'back':
            i = max(0, i - op[1])
            out.append(hist[i])
        else:
            i = min(len(hist) - 1, i + op[1])
            out.append(hist[i])
    return out
